414:export async function hold(page: Page, personId: string, f: { from?: string; to?: string }): Promise<boolean> {
416:  const dated = f.from !== undefined || f.to !== undefined || (await r.getByTestId('person-hold-from').count()) > 0;
417:  const wasText = await shown(r.getByTestId('person-hold'));
418:  const lines = r.getByTestId('person-hold-line');
420:  await setField(r, 'person-hold-from', f.from);
421:  await setField(r, 'person-hold-to', f.to);
422:  await r.getByTestId('person-hold-toggle').click();
425:    : await shown(r.getByTestId('person-hold')) !== wasText,
426:    r.getByTestId('person-error'), 'hold');
642:/** Hold the selected people together: how many were held. */
643:export async function bulkHold(page: Page, personIds: string[], f: { from?: string; to?: string }): Promise<number | null> {
645:  await setField(page, 'bulk-hold-from', f.from);
646:  await setField(page, 'bulk-hold-to', f.to);
648:  await page.getByTestId('bulk-hold').click();
649:  const n = await countAfter(page, page.getByTestId('bulk-held'), page.getByTestId('person-error'), 'bulk hold', was);
1001:/** Hold or release the claim: true once its held flag flipped. */
1002:export async function holdClaim(page: Page, claimId: string): Promise<boolean> {
1005:  await c.getByTestId('claim-hold').click();
1006:  return until(page, async () => (await shown(c.getByTestId('claim-held'))) !== was, c.getByTestId('claim-error'), 'hold claim');

